#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic 1D and 2D proto-structures over dimensions 'i' and 'j'
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Tuning container: layouts and kernel tuning constants
struct tuning_t {
	// 1D layouts for vectors (all use dimension 'i')
	DEFINE_PROTO_STRUCT(x_layout, i_vec);

	// 2D layout for matrix A: dimensions 'i' (rows) and 'j' (columns)
	// The composition order (j_vec ^ i_vec) means:
	//   - 'j' is outer, 'i' is inner -> column-major layout
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// Tunable block size for the 'i' dimension in the first kernel part.
	// This is used with into_blocks_static to tile accesses to A and x1.
	// It can be adjusted for different cache sizes / architectures.
	static constexpr std::size_t i_block = 128;
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	auto n = x1 | get_length<'i'>();

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)((i % n)) / n;
		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
//
//   x1[i] += sum_j A[i][j] * y_1[j];
//   x2[i] += sum_j A[j][i] * y_2[j];
//
// The implementation below is optimized for data locality:
//
//  - A uses a column-major layout ('j' outer, 'i' inner). For the first
//    part we traverse 'j' outer and 'i' inner, which makes accesses to
//    A and x1 contiguous in memory. We additionally tile the 'i'
//    dimension using into_blocks_static, with a tunable block size.
//
//  - For the second part we use a transposed view A_t of A (via rename)
//    with row-major semantics and iterate 'i' outer / 'j' inner.
//    We accumulate into a scalar register per i, reducing repeated loads
//    and stores of x2[i] and enabling better vectorization.
//
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i] logically as A_t[i][j]
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

	// Effective problem size for dimension 'i'
	const std::size_t n_i = x1 | get_length<'i'>();

	// Choose a safe tile size for 'i':
	//   - never 0
	//   - never larger than the actual length
	std::size_t block_i = tuning.i_block;
	if (block_i == 0) block_i = 1;
	if (block_i > n_i) block_i = n_i;

	// Blocked views of x1 and A along dimension 'i'.
	// into_blocks_static<'i','b','I','i'>(block_i) splits 'i' into:
	//   - 'b' : body/border selector (tuple-like dim, size 2)
	//   - 'I' : block index
	//   - 'i' : index within the block
	//
	// This provides tiles of size block_i for the body ('b'==0) and
	// one (possibly smaller) block for the border ('b'==1). The mapping
	// back to the original 'i' is handled by the structure; the kernel
	// only sees ('b','I','i') and never needs to distinguish body/border.
	auto x1_blocked = x1.get_ref() ^ noarr::into_blocks_static<'i', 'b', 'I', 'i'>(block_i);
	auto A_blocked  = A.get_ref()  ^ noarr::into_blocks_static<'i', 'b', 'I', 'i'>(block_i);

#pragma scop
	// -----------------------------------------------------------------
	// First part:
	//
	// for (j = 0; j < N; j++)
	//   for (i = 0; i < N; i++)
	//     x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// We iterate 'j' outermost to exploit the column-major layout of A:
	//   - For fixed j, A[i][j] is contiguous in 'i'
	//   - x1[i] is also contiguous in 'i'
	//   - y_1[j] is a single scalar reused across all i for that j
	//
	// Tiling in 'i' is performed via into_blocks_static. The effective
	// loop nest is:
	//   for j
	//     const y = y_1[j];
	//     for b in {body, border}
	//       for I (block index)
	//         for i (index in block)
	//           x1[i] += A[i][j] * y;
	// -----------------------------------------------------------------
	noarr::traverser(x1_blocked, y_1_j, A_blocked)
		.template for_dims<'j'>([&](auto trav_j) {
			// trav_j has 'j' fixed; remaining dims are 'b', 'I', 'i'

			// Load y_1[j] once per column j and keep it in a register.
			// The state of trav_j only carries the fixed 'j' index.
			auto state_j = trav_j.state();
			const num_t y_val = y_1_j[state_j];

			// Iterate over blocks in the 'i' dimension: first body, then border.
			trav_j.template for_dims<'b', 'I'>([&](auto trav_j_b_I) {
				// Now 'j', 'b' and 'I' are fixed; 'i' is the only remaining dim.
				trav_j_b_I.for_each([&](auto state) {
					// state contains ('j','b','I','i'); x1_blocked and A_blocked
					// know how to interpret this as the original 'i' index.
					x1_blocked[state] = x1_blocked[state] + A_blocked[state] * y_val;
				});
			});
		});

	// -----------------------------------------------------------------
	// Second part:
	//
	// for (i = 0; i < N; i++)
	//   for (j = 0; j < N; j++)
	//     x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// We use the transposed view A_t so that A_t[i][j] = A[j][i].
	// Layout of A_t is effectively row-major for (i,j), so we iterate
	// 'i' outer / 'j' inner to keep accesses to A_t and y_2_j contiguous.
	//
	// Additionally, we accumulate into a scalar 'acc' per i so that x2[i]
	// is loaded once and stored once, which improves cache behavior and
	// enables better auto-vectorization.
	// -----------------------------------------------------------------
	noarr::traverser(x2, y_2_j, A_t)
		.template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed; remaining dim is 'j'

			// State with only 'i' -> used to index x2[i]
			auto state_i = trav_i.state();

			// Start from the current value of x2[i]
			num_t acc = x2[state_i];

			// Accumulate over j: contiguous in A_t and y_2_j
			trav_i.for_each([&](auto state) {
				// state has ('i','j')
				acc += A_t[state] * y_2_j[state];
			});

			// Write back the accumulated value once
			x2[state_i] = acc;
		});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// common length proto-structure for all dimensions
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);

	// initialize data
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination), if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
