	//
	// We choose the layout as:
	//   scalar<num_t> ^ vector<'j'>() ^ vector<'i'>()
	//
	// This means:
	//   - in A, 'j' is the inner (contiguous) dimension: A[i][j] is row-major
	//   - in the transposed view A_t (swap 'i' and 'j'), 'i' becomes contiguous
	//
	// The first part of the kernel uses A with ('i' outer, 'j' inner),
	// the second part uses A_t with ('j' outer, 'i' inner),
	// so both parts traverse their matrix operand in a cache-friendly way.
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	auto n = x1 | get_length<'i'>();

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)((i % n)) / n;
		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i].
	// Because A is row-major (contiguous in 'j'), A_t is column-major
	// (contiguous in 'i'), which we exploit below.
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------
	// First part:
	//
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// We:
	//   - iterate 'i' (rows) in the outer loop
	//   - iterate 'j' (columns, contiguous in memory) in the inner loop
	//   - keep the running sum for x1[i] in a register and write it back
	//     only once per row to remove the loop-carried dependency on x1[i]
	// ------------------------------------------------------------------
	noarr::traverser(A, x1, y_1_j).template for_dims<'i'>([&](auto row_trav) {
		// State with the current row index 'i'
		auto s_i = row_trav.state();

		// Accumulator for x1[i]; start from the initial value
		num_t acc = x1[s_i];

		// Iterate all columns j in this row ('i' is fixed in row_trav)
		row_trav.for_each([&](auto state) {
			// state contains 'i' and 'j'
			acc += A[state] * y_1_j[state];
		});

		// Store the final value of x1[i]
		x1[s_i] = acc;
	});

	// ------------------------------------------------------------------
	// Second part:
	//
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j < N; j++)
	//       x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// With the transposed view A_t (A_t[i][j] = A[j][i]) this is:
	//
	//   x2[i] += sum_j A_t[i][j] * y_2[j]
	//
	// To improve data locality and enable vectorization, we reorder the
	// loops to:
	//
	//   for (j = 0; j < N; ++j) {
	//     const auto y = y_2[j];
	//     for (i = 0; i < N; ++i)
	//       x2[i] += A_t[i][j] * y;
	//   }
	//
	// This way:
	//   - A_t is accessed with 'i' as the inner (contiguous) dimension,
	//   - x2 is updated contiguously in 'i',
	//   - y_2[j] is loaded once per outer-loop iteration.
	//   The mathematical result is unchanged (only the summation order
	//   over j differs, which is acceptable for floating point).
	// ------------------------------------------------------------------
	noarr::traverser(A_t, x2, y_2_j).template for_dims<'j'>([&](auto col_trav) {
		// Fixed column index 'j'
		auto s_j = col_trav.state();

		// Broadcast y_2[j] to all rows for this column
		const num_t y_val = y_2_j[s_j];

		// Now iterate over all 'i' for this fixed 'j'
		col_trav.for_each([&](auto state) {
			// state has 'i' and 'j'; x2 ignores 'j'
			x2[state] = x2[state] + A_t[state] * y_val;
		});
	});
#pragma endscop
}

} // namespace

