//
//   x1[i] = x1[i] + Σ_j A[i][j] * y_1[j]
//   x2[i] = x2[i] + Σ_j A[j][i] * y_2[j]
//
// The second expression is equivalent to:
//
//   x2[j] = x2[j] + Σ_i A[i][j] * y_2[i]
//
// Therefore we can fuse both into a single double loop:
//
//   for (i) for (j) {
//     x1[i] += A[i][j] * y_1[j];
//     x2[j] += A[i][j] * y_2[i];
//   }
//
// This keeps the exact per-element update sequence for each x1[i] and x2[i],
