	// with a single state { 'i', 'j' }.
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto x2_j  = x2.get_ref() ^ noarr::rename<'i', 'j'>();

#pragma scop
	// Fused matrix-vector and transposed-matrix-vector multiplication.
	//
	// Traversal strategy:
	//   - Outer dimension: 'i'  (rows of A, and indices of x1 and y_2)
	//   - Inner dimension: 'j'  (columns of A, and indices of y_1 and x2)
	//
	// For each fixed 'i' we:
	//   1. Load y_2[i] once (reused for all j).
	//   2. Iterate over all 'j' (contiguous in memory for A and y_1_j).
	//      For each (i, j) we perform:
	//        x1[i] += A[i][j] * y_1[j];
	//        x2[j] += A[i][j] * y_2[i];
	noarr::traverser(x1, x2_j, y_1_j, y_2, A)
		// Outer loop over 'i'
		.template for_dims<'i'>([=](auto trav_i) {
			// trav_i has 'i' fixed and only 'j' remaining to iterate.
			// y_2 is 1D over 'i', so we can treat trav_i as a state for it.
			const num_t y2_i = y_2[trav_i];

			// Inner loop over 'j' (A's inner, contiguous dimension).
			trav_i.for_each([=](auto state) {
				// state contains both 'i' and 'j'.

				// Cache the matrix element and y_1[j] in registers to avoid
				// redundant loads and to make the computation more explicit.
				const num_t a_ij = A[state];
				const num_t y1_j = y_1_j[state];

				// First part:
				//   x1[i] = x1[i] + A[i][j] * y_1[j];
				// x1 is indexed by 'i' only; 'j' in the state is ignored.
				x1[state] = x1[state] + a_ij * y1_j;

				// Second part (rewritten):
				//   x2[j] = x2[j] + A[i][j] * y_2[i];
				//
				// x2_j is a renamed view of x2 indexed by 'j', so indexing
				// it with the same state uses the 'j' coordinate.
				x2_j[state] = x2_j[state] + a_ij * y2_i;
			});
		});
#pragma endscop
}

} // namespace

