constexpr auto j_vec = noarr::vector<'j'>();

// Tunable tile size for the inner 'j' dimension in the kernel.
//
// This is used through noarr::into_blocks_dynamic to block the traversal
// of the 'j' dimension. It is a compile-time constant so that the compiler
// can see a fixed block size and better optimize / vectorize the inner loop.
// Adjust this constant to tune for a given cache hierarchy.
constexpr std::size_t J_BLOCK = 64;

struct tuning {
	// 1D layouts for vectors (all use dimension 'i')
	DEFINE_PROTO_STRUCT(x_layout, i_vec);

	// 2D layout for matrix A: dimensions 'i' (rows) and 'j' (columns)
	// The composition j_vec ^ i_vec means:
	//   scalar<num_t>() ^ j_vec ^ i_vec
	//   -> dimensions are 'i' (outer) and 'j' (inner), i.e., row-major in 'j'.
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A:  2D over 'i' x 'j'
	using namespace noarr;

	auto n = x1 | get_length<'i'>();

	// Initialize the four vectors over 'i'
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)((i % n)) / n;
		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
//
// We keep the mathematical computation identical to the original:
//
//   First part:
//     for (i = 0; i < N; i++)
//       for (j = 0; j < N; j++)
//         x1[i] = x1[i] + A[i][j] * y_1[j];
//
//   Second part:
//     for (i = 0; i < N; i++)
//       for (j = 0; j < N; j++)
//         x2[i] = x2[i] + A[j][i] * y_2[j];
//
// but we express the loop nests using Noarr traversers and apply blocking
// on the inner 'j' dimension using noarr::into_blocks_dynamic.
// The blocking preserves the i-then-j iteration order (j still increases
// monotonically inside each i), but improves locality and exposes
// vectorization opportunities. For each i we also keep a scalar accumulator
// in a register and write back to x1/x2 only once, reducing memory traffic.
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// Views of y_1 and y_2 as vectors over 'j' (needed for y_[*][j])
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();
	auto y_2_j = y_2.get_ref() ^ noarr::rename<'i', 'j'>();

	// Transposed view of A to access A[j][i] as A_t[i][j]
	//   A_t(i, j) = A(j, i)
	auto A_t = A.get_ref() ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------
	// First part:
	//   x1[i] += sum_j A[i][j] * y_1[j]
	//
	// Outer loop over 'i'.
	// For each fixed i we:
	//   - read x1[i] into a scalar accumulator
	//   - traverse A and y_1_j along 'j' in tiles of size J_BLOCK
	//     using into_blocks_dynamic<'j','J','j','p'>.
	//     The extra 'p' dimension (presence flag) is used internally by
	//     the structure to discard out-of-range elements in the last
	//     (possibly partial) block; traverser only yields valid elements.
	//   - accumulate into the scalar
	//   - write back to x1[i] once at the end of the i-iteration
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		// State fixing only the current 'i'
		auto state_i = trav_i.state();

		// Start from the current value of x1[i]
		num_t acc = x1[state_i];

		// Block the 'j' dimension. J is the block index, j the index within
		// the block, p is the presence dimension (length 0 or 1).
		// We use a static block size so the compiler can optimize the loop.
		auto trav_i_blocked =
			trav_i.order(noarr::into_blocks_dynamic<'j', 'J', 'j', 'p'>(noarr::lit<J_BLOCK>));

		// Iterate over all blocks in 'j' for this fixed 'i'
		trav_i_blocked.template for_dims<'J'>([&](auto trav_block) {
			// Within a block, traverse all valid (j, p) combinations.
			// The global j index still increases monotonically from 0 to N-1
			// across all blocks, so the summation order per i is unchanged.
			trav_block.for_each([&](auto state) {
				acc += A[state] * y_1_j[state];
			});
		});

		// Store the accumulated result back to x1[i]
		x1[state_i] = acc;
	});

	// ------------------------------------------------------------------
	// Second part:
	//   x2[i] += sum_j A[j][i] * y_2[j]
	//
	// We work with the transposed view A_t where:
	//   A_t(i, j) = A(j, i)
	//
	// The traversal pattern mirrors the first part. Again:
	//   - outer loop over 'i'
	//   - blocked traversal over 'j' using into_blocks_dynamic
	//   - scalar accumulator per i, written back once
	traverser(A_t).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();

		num_t acc = x2[state_i];

		auto trav_i_blocked =
			trav_i.order(noarr::into_blocks_dynamic<'j', 'J', 'j', 'p'>(noarr::lit<J_BLOCK>));

		trav_i_blocked.template for_dims<'J'>([&](auto trav_block) {
			trav_block.for_each([&](auto state) {
				acc += A_t[state] * y_2_j[state];
			});
		});

		x2[state_i] = acc;
	});
#pragma endscop
}

} // namespace

